SELECT subscription_id
FROM subscriptions
WHERE status = 'active';

SELECT DISTINCT account_id
FROM subscriptions
WHERE status = 'active';

SELECT invoice_id, MAX(attempted_at) AS latest_dunning_attempt_at
FROM dunning_attempts
GROUP BY invoice_id;

SELECT customer_id, COUNT(alert_id) FILTER (WHERE status = 'open') AS open_alerts
FROM alerts
GROUP BY customer_id;

